import Foundation
import MemosCore

/// The bytes the running server actually writes.
///
/// `liveFrames` was GENERATED by running memos-ng's own frame writer — `sse_event`,
/// `app/routers/assets.py:721-722` — over the two payload shapes its call sites build: the
/// non-ready snapshot row (`app/routers/assets.py:748`, built at `:802`) and the synthetic ready
/// event merged with `_ready_meta` (`app/routers/assets.py:757-761`, read back at `:819`); line
/// numbers as of memos-ng a1d493c. The spacing is `json.dumps`'s, not a guess:
/// `{"uid": "…"}`, not `{"uid":"…"}`.
enum SSEFixture {
    static let liveFrames: [String] = [
        #"data: {"uid": "a1b2c3d4", "status": "pending", "progress_pct": 0}"# + "\n\n",
        #"data: {"uid": "a1b2c3d4", "status": "processing", "progress_pct": 37}"# + "\n\n",
        #"data: {"uid": "a1b2c3d4", "status": "ready", "progress_pct": 100, "width": 4032, "#
            + #""height": 3024, "blurhash": "LEHV6nWB2yk8pyo0adR*.7kCMdnj"}"# + "\n\n",
        #"data: {"uid": "e5f6a7b8", "status": "failed", "progress_pct": 12}"# + "\n\n",
        #"data: {"uid": "e5f6a7b8", "status": "ready", "progress_pct": 100, "width": null, "#
            + #""height": null, "blurhash": null}"# + "\n\n",
    ]

    /// One upload's whole lifecycle, as one stream.
    static let liveStream = liveFrames.joined()

    /// What the five frames decode to. Written out rather than derived, so the test states the
    /// contract instead of agreeing with the parser about it.
    static let liveEvents: [MediaEvent] = [
        MediaEvent(uid: "a1b2c3d4", status: .pending, progressPercent: 0),
        MediaEvent(uid: "a1b2c3d4", status: .processing, progressPercent: 37),
        MediaEvent(
            uid: "a1b2c3d4",
            status: .ready,
            progressPercent: 100,
            width: 4032,
            height: 3024,
            blurhash: "LEHV6nWB2yk8pyo0adR*.7kCMdnj"
        ),
        MediaEvent(uid: "e5f6a7b8", status: .failed, progressPercent: 12),
        MediaEvent(uid: "e5f6a7b8", status: .ready, progressPercent: 100),
    ]
}

/// A connection the fake server is scripted to hand over.
struct ScriptedConnection: Sendable {
    var statusCode = 200
    /// Delivered in exactly these pieces — the boundaries are half of what is under test.
    var chunks: [[UInt8]] = []
    /// The connection could not be made at all (offline, DNS, TLS).
    var throwsOnConnect = false
    /// Opened, then died with the chunks half-written.
    var failsMidBody = false
    /// Never ends by itself, the way a real connection behaves while work is still in flight.
    var staysOpen = false

    static func whole(_ body: String) -> ScriptedConnection {
        ScriptedConnection(chunks: [Array(body.utf8)])
    }

    /// One byte per chunk: every possible boundary, all at once.
    static func bytewise(_ body: String) -> ScriptedConnection {
        ScriptedConnection(chunks: Array(body.utf8).map { [$0] })
    }

    static func status(_ code: Int) -> ScriptedConnection {
        ScriptedConnection(statusCode: code)
    }

    static func unreachable() -> ScriptedConnection {
        ScriptedConnection(throwsOnConnect: true)
    }

    static func dropping(after body: String = "") -> ScriptedConnection {
        ScriptedConnection(chunks: body.isEmpty ? [] : [Array(body.utf8)], failsMidBody: true)
    }

    static func open(_ body: String) -> ScriptedConnection {
        ScriptedConnection(chunks: [Array(body.utf8)], staysOpen: true)
    }
}

struct DroppedConnection: Error {}

/// Counts how many scripted bodies were torn down — the evidence that cancelling the consumer
/// closes the connection rather than leaking it.
final class TerminationCounter: @unchecked Sendable {
    private let lock = NSLock()
    private var count = 0

    func increment() {
        lock.withLock { count += 1 }
    }

    var value: Int { lock.withLock { count } }
}

/// A server that answers from a script, and remembers what it was asked.
actor ScriptedSSETransport: SSEConnecting {
    private var script: [ScriptedConnection]
    private(set) var requests: [URLRequest] = []
    private let terminations = TerminationCounter()

    init(_ script: [ScriptedConnection] = []) {
        self.script = script
    }

    var connectCount: Int { requests.count }

    /// How many scripted bodies have been torn down.
    func terminationCount() -> Int { terminations.value }

    func header(_ name: String, of index: Int) -> String? {
        guard index < requests.count else { return nil }
        return requests[index].value(forHTTPHeaderField: name)
    }

    func url(of index: Int) -> String? {
        guard index < requests.count else { return nil }
        return requests[index].url?.absoluteString
    }

    func connect(_ request: URLRequest) async throws -> SSEConnection {
        requests.append(request)
        // Past the end of the script this server behaves like the real one with nothing in
        // flight: it opens and closes immediately (`app/routers/assets.py:763-764`). A test that
        // over-runs its script is then bounded by the sleeper's budget instead of hanging.
        let scripted = script.isEmpty ? ScriptedConnection() : script.removeFirst()
        if scripted.throwsOnConnect { throw URLError(.notConnectedToInternet) }
        let counter = terminations
        let body = AsyncThrowingStream<[UInt8], any Error> { continuation in
            continuation.onTermination = { _ in counter.increment() }
            for chunk in scripted.chunks { continuation.yield(chunk) }
            if scripted.failsMidBody {
                continuation.finish(throwing: DroppedConnection())
            } else if !scripted.staysOpen {
                continuation.finish()
            }
        }
        return SSEConnection(statusCode: scripted.statusCode, body: body)
    }
}

/// Waiting, recorded instead of served.
actor RecordingSleeper: SSESleeper {
    private(set) var waits: [TimeInterval] = []
    private let budget: Int

    init(budget: Int = 8) {
        self.budget = budget
    }

    func sleep(for duration: TimeInterval) async throws {
        waits.append(duration)
        // The reconnect loop is infinite by design. Ending the wait with an error is exactly how
        // a real cancellation reaches it, and it is what keeps a test finite.
        if waits.count >= budget { throw CancellationError() }
    }
}

/// The identity clock, scripted to move at a chosen point in the run.
///
/// It counts READS: the client reads it once to take its fence, once before each connection and
/// once per chunk delivered, so a rotation can be placed at exactly the gate under test.
actor ScriptedGeneration {
    private var reads = 0
    private let rotatesAfter: Int

    init(rotatesAfter: Int = .max) {
        self.rotatesAfter = rotatesAfter
    }

    var readCount: Int { reads }

    func current() -> Int {
        reads += 1
        return reads > rotatesAfter ? 1 : 0
    }
}

enum LiveStub {
    static let baseURL = URL(string: "https://memos.example.invalid")!
    static let token = "memos_pat_live"

    static func client(
        transport: ScriptedSSETransport,
        sleeper: RecordingSleeper,
        generation: ScriptedGeneration = ScriptedGeneration(),
        credentials: MediaEventCredentials? = MediaEventCredentials(
            baseURL: LiveStub.baseURL,
            token: LiveStub.token
        ),
        backoff: SSEBackoff = SSEBackoff(),
        idleReconnectDelay: TimeInterval = 15
    ) -> MediaEventClient {
        MediaEventClient(
            credentials: { credentials },
            generation: { await generation.current() },
            backoff: backoff,
            idleReconnectDelay: idleReconnectDelay,
            transport: transport,
            sleeper: sleeper
        )
    }
}

extension MediaEventClient {
    /// Runs the channel until it stops, or until `limit` items have arrived — whichever comes
    /// first. Leaving the loop is what cancels the channel, so this is also the shutdown path.
    func collect(limit: Int = 40) async -> [MediaEventStreamItem] {
        var items: [MediaEventStreamItem] = []
        for await item in stream() {
            items.append(item)
            if case .state(.stopped) = item { break }
            if items.count >= limit { break }
        }
        return items
    }
}

extension [MediaEventStreamItem] {
    var events: [MediaEvent] {
        compactMap {
            guard case .event(let event) = $0 else { return nil }
            return event
        }
    }

    var states: [MediaEventConnectionState] {
        compactMap {
            guard case .state(let state) = $0 else { return nil }
            return state
        }
    }
}
